using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the database encryption key. Usually the encryption key is never changed and is stored in some OS keychain
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetDatabaseEncryptionKeyAsync(byte[] newEncryptionKey = default)
    {

           using var activity =  StartCallActivity("SetDatabaseEncryptionKeyAsync", typeof(SetDatabaseEncryptionKey).FullName ?? "SetDatabaseEncryptionKeyAsync");

           try
           {
             return client.SetDatabaseEncryptionKeyAsync(newEncryptionKey);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd